fn replace_chars(s: &[char], old: char, new: char) -> Vec<char> {
    let mut result = Vec::with_capacity(s.len());
    for &c in s {
        if c == old {
            result.push(new);
        } else {
            result.push(c);
        }
    }
    result
}

